package com.apexbank.treasury.graphql;

import com.apexbank.treasury.dto.TransferPayload;
import com.apexbank.treasury.dto.WireTransferInput;
import com.apexbank.treasury.entity.Account;
import com.apexbank.treasury.repository.AccountRepository;
import com.apexbank.treasury.security.BankUserPrincipal;
import com.apexbank.treasury.service.WireExecutionService;
import org.springframework.graphql.data.method.annotation.Argument;
import org.springframework.graphql.data.method.annotation.MutationMapping;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import java.util.UUID;

@Controller
public class WireTransferGraphQLController {

    private final AccountRepository accountRepository;
    private final WireExecutionService wireExecutionService;

    public WireTransferGraphQLController(AccountRepository accountRepository, WireExecutionService wireExecutionService) {
        this.accountRepository = accountRepository;
        this.wireExecutionService = wireExecutionService;
    }

    @MutationMapping
    public TransferPayload initiateWireTransfer(
            @Argument UUID debitAccountId,
            @Argument WireTransferInput input,
            @AuthenticationPrincipal BankUserPrincipal principal) {
        Account debitAccount = accountRepository.findById(debitAccountId)
                .orElseThrow(() -> new IllegalArgumentException("Debit account not found: " + debitAccountId));
        if (!debitAccount.getOrganizationId().equals(principal.getOrganizationId()) || !debitAccount.isAuthorizedSignatory(principal.getUsername())) {
            throw new AccessDeniedException("Caller is not an authorized signatory on debit account: " + debitAccountId);
        }
        return wireExecutionService.executeWire(debitAccount, input.getRecipientIban(), input.getAmount(), input.getCurrency());
    }
}
